INSERT INTO public.aptitude_questions (category, topic, difficulty, question, options, correct_option, explanation) VALUES
('Quantitative', 'Percentages', 'Intermediate', 'A shopkeeper marks an item at 25% above cost price and allows a discount of 10% for cash payment. What is his profit percentage?', '["10%","12.5%","15%","17.5%"]'::jsonb, 1, 'Let CP = 100. Marked Price (MP) = 125. Selling Price with 10% discount = 125 * 0.9 = 112.5. Profit = 112.5 - 100 = 12.5%.'),
('Quantitative', 'Profit and Loss', 'Beginner', 'If the cost price of 12 pens is equal to the selling price of 8 pens, find the gain percentage.', '["25%","33.33%","50%","66.67%"]'::jsonb, 2, 'Let CP of 1 pen = 1. CP of 8 pens = 8. SP of 8 pens = CP of 12 pens = 12. Profit = 12 - 8 = 4. Gain % = (4 / 8) * 100 = 50%.'),
('Quantitative', 'Time and Work', 'Intermediate', 'A can complete a piece of work in 12 days, and B can complete the same work in 18 days. If they work together for 4 days, what fraction of the work is left?', '["1/3","4/9","5/9","2/3"]'::jsonb, 1, '1 day work of A+B = (1/12) + (1/18) = 5/36. 4 days work = 4 * (5/36) = 20/36 = 5/9. Work left = 1 - 5/9 = 4/9.'),
('Logical Reasoning', 'Number Systems', 'Frequently Asked', 'Find the next number in the series: 3, 7, 15, 31, 63, ?', '["126","127","128","129"]'::jsonb, 1, 'The pattern is (2 * n) + 1. 63 * 2 + 1 = 127.'),
('Logical Reasoning', 'Logical Puzzles', 'Frequently Asked', 'Pointing to a photograph of a man, Rahul said, ''His mother is the only daughter of my mother.'' How is Rahul related to the person in the photograph?', '["Father","Uncle","Brother","Maternal Uncle"]'::jsonb, 3, 'Rahul''s mother''s only daughter is Rahul''s sister. The man''s mother is Rahul''s sister. Thus, Rahul is the maternal uncle.'),
('Quantitative', 'Time, Speed and Distance', 'Advanced', 'A train 150 meters long takes 15 seconds to cross a bridge 300 meters long. What is the speed of the train in km/h?', '["72 km/h","90 km/h","108 km/h","120 km/h"]'::jsonb, 2, 'Total distance = 150 + 300 = 450 meters. Speed in m/s = 450 / 15 = 30 m/s. Speed in km/h = 30 * (18 / 5) = 108 km/h.'),
('Quantitative', 'Probability', 'Intermediate', 'Two dice are rolled simultaneously. What is the probability that the sum of the numbers obtained is a prime number?', '["5/12","7/18","1/2","5/18"]'::jsonb, 0, 'Prime sums possible: 2, 3, 5, 7, 11. Count of outcomes: 2 (1), 3 (2), 5 (4), 7 (6), 11 (2) = 15 out of 36. Probability = 15/36 = 5/12.'),
('Quantitative', 'Ratio and Proportion', 'Beginner', 'The ratio of the ages of A and B is 4:5. Six years hence, the ratio of their ages will become 5:6. What is the present age of A?', '["20 years","24 years","28 years","30 years"]'::jsonb, 1, 'Let ages be 4x and 5x. (4x + 6) / (5x + 6) = 5/6 => 24x + 36 = 25x + 30 => x = 6. Present age of A = 4 * 6 = 24 years.'),
('Quantitative', 'Average', 'Beginner', 'The average score of a batsman in 10 innings was 44. How many runs must he score in the 11th inning to raise his average to 48?', '["84","88","92","96"]'::jsonb, 1, 'Total runs in 10 innings = 10 * 44 = 440. Required total in 11 innings = 11 * 48 = 528. Required runs = 528 - 440 = 88.'),
('Quantitative', 'Simple and Compound Interest', 'Intermediate', 'A sum of money invested at Simple Interest doubles itself in 8 years. In how many years will it treble (become 3 times) at the same rate?', '["12 years","14 years","16 years","20 years"]'::jsonb, 2, 'Doubling means SI = P in 8 years. Trebling means SI = 2P. Time taken for double the interest = 2 * 8 = 16 years.'),
('Quantitative', 'Simple and Compound Interest', 'Intermediate', 'Find the compound interest on $10,000 for 2 years at 10% per annum, compounded annually.', '["$2,000","$2,100","$2,200","$2,050"]'::jsonb, 1, 'Amount = 10,000 * (1 + 0.10)^2 = 10,000 * 1.21 = $12,100. CI = 12,100 - 10,000 = $2,100.'),
('Quantitative', 'Permutation and Combination', 'Intermediate', 'In how many distinct ways can the letters of the word ''LEADER'' be arranged?', '["720","360","120","180"]'::jsonb, 1, 'Word has 6 letters with ''E'' repeating 2 times. Total permutations = 6! / 2! = 720 / 2 = 360.'),
('Quantitative', 'Time and Work', 'Beginner', 'Pipe A can fill a tank in 20 minutes and Pipe B can fill it in 30 minutes. If both pipes are opened together, how long will it take to fill the tank?', '["10 minutes","12 minutes","15 minutes","18 minutes"]'::jsonb, 1, 'Combined rate = 1/20 + 1/30 = 5/60 = 1/12. Time taken = 12 minutes.'),
('Quantitative', 'Time, Speed and Distance', 'Intermediate', 'Two cars start from two cities 300 km apart and travel towards each other at speeds of 60 km/h and 40 km/h respectively. After how many hours will they meet?', '["2.5 hours","3 hours","3.5 hours","4 hours"]'::jsonb, 1, 'Relative speed = 60 + 40 = 100 km/h. Time to meet = 300 / 100 = 3 hours.'),
('Quantitative', 'Number Systems', 'Frequently Asked', 'What is the remainder when (7^19 + 2) is divided by 6?', '["1","2","3","5"]'::jsonb, 2, '7 mod 6 = 1. Therefore 7^19 mod 6 = 1^19 mod 6 = 1. Adding 2 gives (1 + 2) mod 6 = 3 mod 6 = 3.'),
('Logical Reasoning', 'Logical Reasoning', 'Intermediate', 'Statements: All cats are dogs. All dogs are birds. Conclusions: I. All cats are birds. II. All birds are cats.', '["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"]'::jsonb, 0, 'Cats ⊆ Dogs ⊆ Birds implies all cats are birds (I follows). But not all birds are necessarily cats (II does not follow).'),
('Logical Reasoning', 'Coding Patterns', 'Frequently Asked', 'If in a certain code language ''PENCIL'' is written as ''QGODKN'', how is ''PAPER'' written in that same code?', '["QBQFS","QCQFS","QBQES","QBRFS"]'::jsonb, 0, 'Pattern is +1 for each letter: P(+1)->Q, A(+1)->B, P(+1)->Q, E(+1)->F, R(+1)->S. Hence PAPER becomes QBQFS.'),
('Logical Reasoning', 'Logical Reasoning', 'Beginner', 'A person walks 10 meters North, turns right and walks 15 meters, then turns right again and walks 10 meters. How far and in which direction is he from his starting point?', '["15 meters East","15 meters West","10 meters East","25 meters North"]'::jsonb, 0, 'Moving 10m North and 10m South cancels the vertical displacement. The horizontal displacement is 15m to the East.'),
('Data Interpretation', 'Basic Data Interpretation', 'Beginner', 'A company produced 1200 units in 2021, 1500 units in 2022, and 1800 units in 2023. What is the percentage growth in production from 2021 to 2023?', '["33.33%","40%","50%","60%"]'::jsonb, 2, 'Increase = 1800 - 1200 = 600 units. Percentage growth = (600 / 1200) * 100 = 50%.'),
('Quantitative', 'Ratio and Proportion', 'Intermediate', 'In what ratio must tea at $62 per kg be mixed with tea at $72 per kg so that the mixture is worth $65 per kg?', '["7:3","3:7","5:3","3:5"]'::jsonb, 0, 'By rule of alligation: (72 - 65) : (65 - 62) = 7 : 3.'),
('Quantitative', 'Basic Quantitative Reasoning', 'Beginner', 'The sum of the present ages of a father and his son is 60 years. Six years ago, father''s age was five times the age of the son. What is the son''s present age?', '["12 years","14 years","16 years","18 years"]'::jsonb, 1, '6 years ago sum was 60 - 12 = 48. Let son''s age 6 yrs ago be x; 5x + x = 48 => x = 8. Son''s present age = 8 + 6 = 14 years.'),
('Quantitative', 'Probability', 'Intermediate', 'A card is drawn at random from a standard well-shuffled pack of 52 cards. What is the probability of getting a King or a Heart?', '["4/13","1/4","17/52","16/52"]'::jsonb, 0, 'Number of Kings = 4, Number of Hearts = 13, King of Hearts = 1. Favorable = 4 + 13 - 1 = 16. Probability = 16/52 = 4/13.'),
('Quantitative', 'Number Systems', 'Frequently Asked', 'What is the smallest 4-digit number that is completely divisible by 12, 15, and 18?', '["1020","1080","1100","1180"]'::jsonb, 1, 'LCM(12, 15, 18) = 180. 1000 / 180 = 5 with remainder 100. Required number = 1000 + (180 - 100) = 1080.'),
('Quantitative', 'Permutation and Combination', 'Frequently Asked', 'In a room of 10 people, everyone shakes hands with everyone else exactly once. How many total handshakes take place?', '["45","50","90","100"]'::jsonb, 0, 'Total handshakes = 10C2 = (10 * 9) / 2 = 45.'),
('Logical Reasoning', 'Number Systems', 'Intermediate', 'Find the missing number in the sequence: 2, 6, 12, 20, 30, 42, ?', '["52","54","56","60"]'::jsonb, 2, 'The terms are n * (n + 1): 1*2=2, 2*3=6, 3*4=12, 4*5=20, 5*6=30, 6*7=42, 7*8 = 56.'),
('Quantitative', 'Time, Speed and Distance', 'Intermediate', 'A boat can travel with a speed of 13 km/h in still water. If the speed of the stream is 4 km/h, find the time taken by the boat to go 68 km downstream.', '["3 hours","4 hours","5 hours","5.5 hours"]'::jsonb, 1, 'Downstream speed = 13 + 4 = 17 km/h. Time = 68 / 17 = 4 hours.'),
('Quantitative', 'Percentages', 'Intermediate', 'The population of a town increases by 10% annually. If its present population is 20,000, what will be the population after 2 years?', '["22,000","24,000","24,200","24,400"]'::jsonb, 2, 'Population after 2 years = 20,000 * (1 + 0.10)^2 = 20,000 * 1.21 = 24,200.'),
('Quantitative', 'Profit and Loss', 'Frequently Asked', 'Find the single equivalent discount percentage for two successive discounts of 20% and 10%.', '["28%","30%","25%","29%"]'::jsonb, 0, 'Equivalent discount = 20 + 10 - (20 * 10 / 100) = 30 - 2 = 28%.'),
('Logical Reasoning', 'Logical Reasoning', 'Intermediate', 'Five friends (P, Q, R, S, T) are sitting in a row facing North. S is between T and Q. Q is to the immediate left of R. P is to the immediate left of T. Who is sitting in the middle?', '["P","T","S","Q"]'::jsonb, 2, 'Arrangement from left to right is P - T - S - Q - R. S is sitting in the exact middle.'),
('Logical Reasoning', 'Logical Reasoning', 'Frequently Asked', 'What is the angle between the hour hand and the minute hand of a clock at 3:30?', '["70 degrees","75 degrees","80 degrees","85 degrees"]'::jsonb, 1, 'Angle = |30*H - (11/2)*M| = |30*3 - (11/2)*30| = |90 - 165| = 75 degrees.'),
('Logical Reasoning', 'Logical Reasoning', 'Frequently Asked', 'If January 1, 2006 was a Sunday, what day of the week was January 1, 2010?', '["Thursday","Friday","Saturday","Sunday"]'::jsonb, 1, 'Odd days: 2006(1) + 2007(1) + 2008(2) + 2009(1) = 5 odd days. Sunday + 5 days = Friday.'),
('Quantitative', 'Time and Work', 'Advanced', 'A and B undertake to do a piece of work for $600. A alone can do it in 6 days while B alone can do it in 8 days. With the help of C, they finish it in 3 days. Find C''s share.', '["$75","$100","$125","$150"]'::jsonb, 0, 'C''s 1-day work = 1/3 - (1/6 + 1/8) = 1/24. Work ratio A:B:C = 4:3:1. C''s share = (1/8) * 600 = $75.'),
('Quantitative', 'Basic Quantitative Reasoning', 'Beginner', 'Which of the following fractions is the largest: 3/4, 5/6, 7/9, 11/13?', '["3/4","5/6","7/9","11/13"]'::jsonb, 3, 'Decimals: 3/4 = 0.75, 5/6 = 0.833, 7/9 = 0.777, 11/13 ≈ 0.846. Hence 11/13 is the largest.'),
('Logical Reasoning', 'Number Systems', 'Beginner', 'Find the odd one out from the given options: 27, 64, 125, 144, 216.', '["27","64","125","144"]'::jsonb, 3, '27=3^3, 64=4^3, 125=5^3, 216=6^3 are all perfect cubes. 144 = 12^2 is a square, not a cube.'),
('Data Interpretation', 'Basic Data Interpretation', 'Beginner', 'A monthly family budget of $4,000 allocates 35% to rent, 25% to food, 15% to savings, and the rest to miscellaneous expenses. How much is spent on miscellaneous expenses?', '["$800","$1,000","$1,200","$600"]'::jsonb, 1, 'Miscellaneous percentage = 100% - (35% + 25% + 15%) = 25%. Amount = 0.25 * 4,000 = $1,000.');
INSERT INTO public.technical_questions (role, topic, difficulty, question, expected_concepts, sample_answer) VALUES
('Software Developer', 'OOP', 'Intermediate', 'Explain the four pillars of Object-Oriented Programming (OOP) with real-world engineering examples.', '["Encapsulation","Abstraction","Inheritance","Polymorphism"]'::jsonb, 'Encapsulation (bundling state and methods within classes with access modifiers), Abstraction (hiding implementation complexity behind interfaces), Inheritance (reusing attributes from a base class), and Polymorphism (ability to take multiple forms via overriding and overloading).'),
('Full Stack Developer', 'DBMS & Databases', 'Intermediate', 'What are ACID properties in database management systems and why are they critical for transaction reliability?', '["Atomicity","Consistency","Isolation","Durability"]'::jsonb, 'Atomicity ensures all-or-nothing transactions, Consistency guarantees state transitions adhere to constraints, Isolation prevents concurrent race collisions, and Durability ensures committed writes persist even through power outages.'),
('Frontend Developer', 'Web Performance & DOM', 'Intermediate', 'What is the difference between Virtual DOM and Real DOM, and how does the reconciliation algorithm optimize rendering?', '["Virtual DOM tree","Diffing algorithm","Batch DOM updates","Reflow and Repaint reduction"]'::jsonb, 'The Real DOM triggers expensive layout reflows on every mutation. The Virtual DOM creates an in-memory lightweight representation, computes minimal tree differences (diffing), and batch updates only the affected nodes.'),
('Backend Developer', 'APIs & Web Services', 'Intermediate', 'What is the architectural difference between REST and GraphQL? In what scenarios would you choose one over the other?', '["Fixed endpoints vs Single endpoint","Over-fetching and Under-fetching","Schema & Type safety","HTTP caching"]'::jsonb, 'REST uses resource-centric HTTP endpoints with standard methods and native caching. GraphQL uses a single POST endpoint with a strongly typed schema allowing clients to declare exact data shapes, eliminating over-fetching.'),
('Full Stack Developer', 'Authentication & Security', 'Advanced', 'How does JWT (JSON Web Token) authentication work, and how do you mitigate risks like token theft and session revocation?', '["Header.Payload.Signature","Statelessness","HttpOnly Cookies","Short-lived Access Tokens & Refresh Tokens"]'::jsonb, 'JWTs encode claims signed cryptographically. Mitigation includes storing tokens in secure HttpOnly SameSite cookies, issuing short-lived access tokens (15m) paired with rotating refresh tokens stored in a revoked-list database.'),
('Software Developer', 'Operating Systems', 'Intermediate', 'Explain the difference between a Process and a Thread. How does context switching overhead differ between them?', '["Separate address space vs Shared memory","Context switching overhead","Process Control Block (PCB) vs TCB","Inter-Process Communication (IPC)"]'::jsonb, 'A process has its own isolated virtual memory space and resources, while threads share the process memory heap, code, and file descriptors. Thread context switching is substantially faster because virtual memory mappings do not need to be reloaded.'),
('Software Developer', 'Computer Networks', 'Intermediate', 'Describe the TCP 3-Way Handshake. Why is it necessary before data transmission compared to UDP?', '["SYN, SYN-ACK, ACK","Sequence numbers initialization","Reliable ordered delivery","Connection-oriented vs Connectionless"]'::jsonb, 'Client sends SYN with initial sequence number, server responds with SYN-ACK, and client sends ACK. This synchronizes sequence numbers and establishes a reliable, bidirectional, ordered data transmission stream before payloads are exchanged.'),
('Backend Developer', 'DBMS & Databases', 'Advanced', 'How does database indexing work under the hood? Contrast B-Tree indexes with Hash indexes.', '["B-Tree / B+Tree structure","O(log N) lookup","Range queries support","Hash index O(1) exact match limitations"]'::jsonb, 'B-Tree indexes maintain balanced, sorted tree hierarchies optimal for range scans, sorting, and equality searches in O(log N) time. Hash indexes provide O(1) lookups for exact matches but cannot perform range searches or ORDER BY queries.'),
('Software Developer', 'SQL & Databases', 'Beginner', 'Explain the difference between INNER JOIN, LEFT JOIN, RIGHT JOIN, and FULL OUTER JOIN with practical examples.', '["Matching rows only","All left rows with NULL right","All right rows with NULL left","Union of all records"]'::jsonb, 'INNER JOIN returns only matching records from both tables. LEFT JOIN returns all records from the left table with matched right records (or NULL). RIGHT JOIN does the reverse, and FULL OUTER JOIN returns all rows from both tables.'),
('Java Developer', 'Java Internals & JVM', 'Intermediate', 'How does Garbage Collection work in the JVM? Explain the Young, Old, and Permanent/Metaspace generations.', '["Mark and Sweep algorithm","Eden, Survivor (S0/S1), Tenured/Old generation","Minor GC vs Major GC","Metaspace memory"]'::jsonb, 'Objects are allocated in the Eden space. Surviving objects migrate through Survivor spaces during Minor GCs and get promoted to the Old Generation. Major GCs collect long-lived objects when Tenured memory fills up.'),
('Python Developer', 'Python Internals', 'Intermediate', 'What is the Global Interpreter Lock (GIL) in CPython, and how do you achieve true parallelism in CPU-bound vs I/O-bound Python programs?', '["CPython mutex","Single thread bytecode execution","multiprocessing module for CPU tasks","asyncio / threading for I/O tasks"]'::jsonb, 'The GIL is a mutex preventing multiple native threads from executing Python bytecodes simultaneously. For I/O-bound tasks, threading or asyncio achieves concurrency; for CPU-bound tasks, multiprocessing or C-extensions bypass the GIL.'),
('Frontend Developer', 'JavaScript Internals', 'Intermediate', 'Explain the JavaScript Event Loop, Call Stack, Microtask Queue, and Macrotask Queue execution order.', '["Call stack execution","Microtasks (Promises, queueMicrotask)","Macrotasks (setTimeout, setInterval)","Event loop prioritization"]'::jsonb, 'Synchronous code runs on the Call Stack. When empty, the event loop drains ALL microtasks (Promises, process.nextTick) before picking the next single macrotask (setTimeout, DOM events, I/O).'),
('Software Developer', 'System Design', 'Advanced', 'Explain the CAP Theorem and how distributed databases make trade-offs between Consistency, Availability, and Partition Tolerance.', '["Consistency","Availability","Partition Tolerance","CP vs AP database systems"]'::jsonb, 'In a network partition (P), a distributed system can guarantee either Consistency (C) by rejecting stale writes/reads or Availability (A) by continuing to serve local responses at the expense of temporary divergence.'),
('Backend Developer', 'Caching & Performance', 'Intermediate', 'Compare Cache-Aside, Write-Through, and Write-Back caching strategies. When is Redis preferred over Memcached?', '["Cache-Aside pattern","Write-Through latency","Write-Back async durability risk","Redis data structures & persistence"]'::jsonb, 'Cache-Aside queries cache first and populates on miss. Write-Through writes simultaneously to cache and DB. Write-Back writes to cache and syncs DB asynchronously. Redis is chosen for rich data structures, pub/sub, and persistence.'),
('Software Developer', 'Web Security', 'Intermediate', 'Explain Cross-Site Scripting (XSS) and Cross-Site Request Forgery (CSRF). How do you defend modern web applications against them?', '["Stored/Reflected XSS","Content Security Policy (CSP)","HTML escaping & sanitization","CSRF tokens & SameSite cookies"]'::jsonb, 'XSS executes unauthorized client scripts; defended with HTML context escaping and strict CSP headers. CSRF tricks authenticated browsers into submitting malicious requests; defended using Anti-CSRF tokens and SameSite=Strict cookies.'),
('Software Developer', 'Computer Networks & Security', 'Intermediate', 'How does an HTTPS TLS/SSL handshake establish secure communication? Explain symmetric vs asymmetric encryption in this context.', '["TLS certificate verification","Asymmetric key exchange (RSA/Diffie-Hellman)","Symmetric session key","Data integrity / HMAC"]'::jsonb, 'The client verifies the server certificate using CA public keys. Asymmetric encryption negotiates a shared secret session key. Subsequent HTTP traffic is encrypted using fast symmetric encryption (AES-GCM) with this shared key.'),
('Software Developer', 'DBMS & Databases', 'Intermediate', 'What is Database Normalization (1NF, 2NF, 3NF)? When is deliberate Denormalization justified in read-heavy applications?', '["1NF atomic values","2NF partial dependency removal","3NF transitive dependency removal","Denormalization for fast joins"]'::jsonb, '1NF enforces atomic columns, 2NF eliminates partial dependencies on composite keys, and 3NF removes transitive dependencies. Denormalization reduces expensive multi-table joins in high-scale read-heavy systems like analytics dashboards.'),
('Software Developer', 'System Design', 'Intermediate', 'Explain the main Load Balancing algorithms (Round Robin, Least Connections, Consistent Hashing) and Layer 4 vs Layer 7 load balancing.', '["Round Robin & Weighted Round Robin","Least Connections","Consistent Hashing for cache locality","L4 (TCP/UDP) vs L7 (HTTP/Path routing)"]'::jsonb, 'Round Robin rotates requests sequentially; Least Connections directs traffic to servers with fewest active sessions. Consistent Hashing minimizes cache misses on node scaling. L4 balances at transport level; L7 inspects HTTP headers, cookies, and URLs.'),
('Software Developer', 'Data Structures & Algorithms', 'Intermediate', 'How do Hash Tables resolve collisions? Compare Separate Chaining with Open Addressing (Linear Probing, Quadratic Probing, Double Hashing).', '["Hash function distribution","Separate Chaining with Linked Lists / Red-Black trees","Linear / Quadratic probing","Load factor & rehashing"]'::jsonb, 'Separate Chaining stores colliding entries in linked lists or balanced trees at the bucket index. Open Addressing searches for adjacent empty slots in the main table array via probing sequences when collisions occur.'),
('Backend Developer', 'Messaging & Microservices', 'Advanced', 'What are the core differences between RabbitMQ (message broker) and Apache Kafka (distributed event streaming log)?', '["Push vs Pull model","Smart broker vs Dumb broker / Smart consumer","Log retention & replayability","Throughput scaling"]'::jsonb, 'RabbitMQ is an AMQP broker that tracks delivery state and deletes messages after ack. Kafka is an immutable, distributed, append-only partitioned log where consumers pull and track their own offsets, allowing historical replay.'),
('Frontend Developer', 'Web Performance', 'Intermediate', 'What are Google Core Web Vitals (LCP, INP, CLS) and what engineering techniques optimize each metric?', '["Largest Contentful Paint (LCP)","Interaction to Next Paint (INP)","Cumulative Layout Shift (CLS)","Image sizing, code splitting, layout stability"]'::jsonb, 'LCP measures load speed (optimized via CDNs, preload headers, and image compression). INP measures user interactivity responsiveness (optimized by yielding to main thread and debouncing). CLS measures layout shifts (fixed by reserving width/height on media).'),
('Software Developer', 'Operating Systems', 'Intermediate', 'What are the four Coffman conditions required for a Deadlock to occur, and how do operating systems prevent or recover from deadlocks?', '["Mutual Exclusion","Hold and Wait","No Preemption","Circular Wait","Banker''s Algorithm & Resource ordering"]'::jsonb, 'Deadlocks require: Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. Prevention breaks one condition, such as enforcing strict global resource hierarchy ordering to make Circular Wait impossible.'),
('Software Developer', 'Clean Architecture & OOP', 'Intermediate', 'Explain the SOLID principles of Object-Oriented Software Design with practical examples of their benefits.', '["Single Responsibility","Open/Closed","Liskov Substitution","Interface Segregation","Dependency Inversion"]'::jsonb, 'Single Responsibility (one reason to change), Open/Closed (open for extension, closed for modification), Liskov Substitution (subtypes must be substitutable for base types), Interface Segregation (focused client interfaces), and Dependency Inversion (depend on abstractions, not concretions).'),
('Backend Developer', 'APIs & Web Architecture', 'Intermediate', 'What does Idempotency mean in HTTP and REST API design? Which HTTP verbs are inherently idempotent and why?', '["Idempotency definition","GET, PUT, DELETE, HEAD vs POST","Idempotency-Key headers in payment gateways"]'::jsonb, 'An operation is idempotent if executing it multiple times produces the exact same server state as a single execution. GET, PUT, DELETE, and HEAD are idempotent; POST is non-idempotent because repeated requests create duplicate resources.'),
('Backend Developer', 'Database Architecture', 'Advanced', 'Compare Horizontal Database Sharding, Vertical Partitioning, and Read Replicas. What challenges arise with cross-shard joins and distributed transactions?', '["Shard key selection","Read/Write split with replicas","Two-Phase Commit (2PC) / Sagas","Cross-shard query latency"]'::jsonb, 'Read replicas scale read queries asynchronously. Vertical partitioning splits wide tables into functional tables. Horizontal sharding splits rows across distinct database instances by shard key. Cross-shard joins require 2PC or Saga patterns to maintain consistency.'),
('Software Developer', 'DevOps & Containers', 'Beginner', 'How do Docker containers differ from Virtual Machines? Explain the role of Linux cgroups and namespaces in container isolation.', '["Shared host OS kernel","Namespaces (PID, NET, MNT)","cgroups (CPU/Memory limits)","Lightweight footprint vs Hypervisor"]'::jsonb, 'VMs run full guest operating systems on top of hypervisors with duplicated kernel overhead. Containers share the host Linux kernel, using namespaces for process/network isolation and cgroups for resource quota enforcement.'),
('Java Developer', 'Spring Boot & Java', 'Intermediate', 'Explain Dependency Injection (DI) and Inversion of Control (IoC) in Spring Boot. What are Bean Scopes (Singleton, Prototype, Request, Session)?', '["Inversion of Control container","Constructor vs Setter injection","Singleton default scope","Prototype fresh instance scope"]'::jsonb, 'IoC delegates object lifecycle and dependency wiring to the Spring container via Dependency Injection. Singleton scope creates a single shared instance per ApplicationContext; Prototype creates a new bean every time requested.'),
('Frontend Developer', 'State Management', 'Intermediate', 'How do unidirectional data flow and state immutability prevent subtle UI synchronization bugs in modern frontend applications?', '["Unidirectional data flow","Immutability & shallow equality checks","Predictable state transitions","Pure functions and reducers"]'::jsonb, 'Unidirectional data flow ensures data travels in one direction (Action -> State -> View), making transitions predictable. Immutability enables shallow reference equality checks (prev !== next), bypassing deep object comparisons during re-renders.'),
('Software Developer', 'Computer Networks', 'Beginner', 'Describe the step-by-step lifecycle of a DNS lookup when a user types a URL into a browser.', '["Browser / OS DNS cache","Recursive DNS resolver","Root nameservers","TLD nameservers","Authoritative nameserver & TTL"]'::jsonb, 'Browser checks local cache and OS resolver. If missing, the recursive resolver queries Root nameserver (.) -> TLD nameserver (.com) -> Authoritative nameserver for domain A records, which returns the IP and caches it with TTL.'),
('Backend Developer', 'System Design', 'Advanced', 'Explain the Token Bucket and Sliding Window Log algorithms for API Rate Limiting. Where should rate limiting be enforced in distributed systems?', '["Token Bucket algorithm","Sliding Window Log / Counter","API Gateway / Reverse Proxy layer","Redis atomic operations"]'::jsonb, 'Token Bucket adds tokens at a fixed rate and allows burst traffic if tokens are available. Sliding Window tracks timestamps in a sorted set to eliminate burst vulnerabilities. Rate limiting is enforced at API Gateways using Redis atomic increments.'),
('Software Developer', 'Algorithms & Complexity', 'Beginner', 'What is Big O notation? Contrast O(1), O(log N), O(N), O(N log N), and O(N^2) with concrete algorithmic examples.', '["Upper bound growth rate","O(1) hash lookup","O(log N) binary search","O(N log N) merge sort","O(N^2) nested loops"]'::jsonb, 'Big O describes worst-case asymptotic growth. O(1) is instant array indexing; O(log N) halves problem size like Binary Search; O(N) is linear scan; O(N log N) is optimal comparison sorting (Merge Sort); O(N^2) is nested iterations (Bubble Sort).'),
('Software Developer', 'Git & Version Control', 'Beginner', 'Explain the difference between `git merge` and `git rebase`. When is one preferred over the other in team workflows?', '["Merge commits & non-destructive history","Rebase linear commit history","Golden Rule of Rebase (never rebase public main)","Interactive rebasing"]'::jsonb, '`git merge` combines branches with a dedicated merge commit preserving exact history timestamps. `git rebase` rewrites feature branch commits on top of the target branch for a clean, linear commit log before merging.');
INSERT INTO public.coding_questions (title, role, topic, difficulty, description, examples, constraints, starter_code, test_cases) VALUES
('Two Sum', 'Software Developer', 'Arrays & Hash Maps', 'Beginner', 'Given an array of integers `nums` and an integer `target`, return indices of the two numbers such that they add up to `target`.
INSERT INTO public.hr_questions (category, question, key_evaluation_points) VALUES
('Introduction', 'Tell me about yourself and walk me through your key achievements in software engineering.', '["Structured chronological narrative (Present -> Past -> Future)","Concrete technical achievements","Clarity and communication confidence"]'::jsonb),
('Problem Solving', 'Describe a challenging technical problem or production bug you solved under tight deadlines. How did you diagnose and resolve it?', '["STAR method structure","Root cause diagnostic capability","Engineering ownership and resilience"]'::jsonb),
